const response = $input.item.json;
const prev = $('Route Action').first().json;

let rawText = '';
try {
  rawText = response.candidates[0].content.parts[0].text;
} catch (e) {
  throw new Error('Gemini API returned an invalid or empty response structure.');
}

let data = {};
try {
  data = JSON.parse(rawText.trim());
} catch (e) {
  throw new Error('Failed to parse Gemini output as JSON: ' + rawText.slice(0, 100));
}

const title = (data.title || 'Impact Circles Announcement').trim().slice(0, 255);
const linkedin = data.linkedin || { content: '', hashtags: [] };
const newsletter = data.newsletter || { subject: '', summary: '', cta: '' };
const website = data.website || { title, slug: '', excerpt: '', markdownContent: '', tags: [] };

const generatedId = 'cp_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);

return {
  id: generatedId,
  title,
  sourcePrompt: prev.sourcePrompt,
  contentType: prev.contentType,
  status: 'draft',
  linkedinContent: JSON.stringify(linkedin),
  newsletterContent: JSON.stringify(newsletter),
  websiteContent: JSON.stringify(website),
  targetChannels: JSON.stringify(prev.targetChannels),
  metadata: JSON.stringify({
    summary: data.summary || '',
    generatedVia: 'n8n_gemini_agent',
    generatedAt: new Date().toISOString()
  })
};

const record = $input.item.json;
if (!record || !record.id) {
  throw new Error('Database persistence failed to return a valid content post.');
}

return {
  success: true,
  post: record
};

const post = $input.item.json;
const req = $('Route Action').first().json;

if (!post || !post.id) {
  return {
    canPublish: false,
    statusCode: 404,
    error: 'Not Found: Content post with ID ' + req.postId + ' does not exist.'
  };
}

// Strict Human Review & Approval Invariant
if (post.status !== 'approved') {
  return {
    canPublish: false,
    statusCode: 400,
    error: 'Strict Invariant Violation: Content post cannot be published unless it has been explicitly approved by a human reviewer. Current status is "' + post.status + '".'
  };
}

// Determine channels to publish
let targetChannels = [];
if (Array.isArray(req.channels) && req.channels.length > 0) {
  targetChannels = req.channels;
} else if (Array.isArray(post.targetChannels)) {
  targetChannels = post.targetChannels;
} else if (typeof post.targetChannels === 'string') {
  try {
    targetChannels = JSON.parse(post.targetChannels);
  } catch (e) {
    targetChannels = ['website', 'linkedin', 'newsletter'];
  }
} else {
  targetChannels = ['website', 'linkedin', 'newsletter'];
}

const logs = [];
const timestamp = Date.now();

for (const ch of targetChannels) {
  const logId = 'log_' + timestamp.toString(36) + '_' + ch + '_' + Math.random().toString(36).substring(2, 6);
  let publishedUrl = null;
  let responsePayload = {};

  if (ch === 'website') {
    let slug = 'announcement-' + timestamp;
    try {
      const web = JSON.parse(post.websiteContent || '{}');
      if (web.slug) slug = web.slug;
    } catch (e) {}
    publishedUrl = 'https://impactcircles.org/news/' + slug;
    responsePayload = { provider: 'Website CMS', slug, mode: 'live_synced' };
  } else if (ch === 'linkedin') {
    publishedUrl = 'https://www.linkedin.com/feed/update/urn:li:share:' + (timestamp + 1000000);
    responsePayload = { provider: 'LinkedIn Marketing API', urn: 'urn:li:share:' + (timestamp + 1000000), mode: 'simulated_sandbox' };
  } else if (ch === 'newsletter') {
    publishedUrl = 'https://impactcircles.substack.com/p/digest-' + timestamp;
    responsePayload = { provider: 'Newsletter Email Broadcast', campaignId: 'camp_' + timestamp, mode: 'simulated_sandbox' };
  }

  logs.push({
    id: logId,
    postId: post.id,
    channel: ch,
    status: 'success',
    publishedUrl,
    responsePayload: JSON.stringify(responsePayload),
    errorMessage: null
  });
}

return {
  canPublish: true,
  postId: post.id,
  targetChannels,
  logs,
  logsJson: JSON.stringify(logs),
  newStatus: 'published'
};

const updatedPost = $input.item.json;
const prev = $('Verify Human Approval & Execute Dispatch').first().json;

return {
  success: true,
  postId: prev.postId,
  status: updatedPost.status || 'published',
  publishedChannels: prev.targetChannels,
  logs: prev.logs
};

const item = $input.item.json;
const errObj = item?.error || item;
const errStatus = Number(errObj?.status || errObj?.statusCode || 0);
const rawMessage = String(errObj?.message || errObj?.description || item?.message || '');

const isRateLimit =
  errStatus === 429 ||
  rawMessage.includes('429') ||
  rawMessage.toLowerCase().includes('too many requests') ||
  rawMessage.toLowerCase().includes('quota');

const isUnavailable =
  errStatus === 503 ||
  rawMessage.includes('503') ||
  rawMessage.toLowerCase().includes('service unavailable');

let statusCode = 502;
let safeMessage = 'AI content generation service failed to produce content.';

if (isRateLimit) {
  statusCode = 429;
  safeMessage = 'AI content generation rate limit reached. Please retry shortly.';
} else if (isUnavailable) {
  statusCode = 503;
  safeMessage = 'AI content generation service temporarily unavailable. Please retry shortly.';
}

return {
  success: false,
  error: safeMessage,
  statusCode
};

return {
  success: false,
  error: 'Database operation failed during content pipeline execution. Please try again.',
  statusCode: 500
};
